import sys, json
Q=[]
def q(topic,title,text,opts,ans,exp,stem=None):
    d=dict(topic=topic,title=title,q=text,opts=opts,ans=ans,exp=exp,pick='בחרו שתי תשובות' if len(ans)==2 else 'בחרו תשובה אחת')
    if stem: d['stem']=stem
    Q.append(d)
q('1.1','שימוש באנליטיקה','אתה מומחה איכות בצוות פיתוח של אפליקציה למכשירים ניידים. לאיזו מהמטרות הבאות ייעשה שימוש בנתוני אנליטיקה של מכשירים ניידים במסגרת אסטרטגיית הבדיקות או תוכנית הבדיקות?',['להגדרת קהל המשתמשים הצפוי של האפליקציה','לגזירת רמות בדיקה, מקרי בדיקה (Test Cases) ונתוני בדיקה','לבחירת סל המכשירים (Device Portfolio) ולתעדוף הרצת הבדיקות','לבחירת סוג האפליקציה ומודל הפיתוח'],[2],'נתוני האנליטיקה מראים באילו מכשירים ובאילו גרסאות המשתמשים באמת משתמשים — ולכן משמשים לבחירת ה-Device Portfolio ולתעדוף הבדיקות.')
q('1.2','מודל עסקי','הצוות שלך מפתח אפליקציה לשימוש בחינם, האוספת חדשות הזמינות לציבור ממקורות שנבחרו על ידי המשתמש, כדי לאפשר לו לקרוא במקום אחד את כל החדשות מהמקורות המועדפים עליו. איזה מהמודלים העסקיים הבאים הוא המתאים ביותר?',['אפליקציית Freemium','אפליקציה המבוססת על פרסומות','אפליקציה בתשלום','אפליקציה המבוססת על עסקאות'],[1],'האפליקציה חינמית ואין בה תכונות פרימיום או עסקאות — ההכנסה תגיע מפרסומות.')
q('1.3','Feature Phones','איזו מהטענות הבאות נכונה לגבי טלפונים בעלי תכונות מוגבלות (Feature phones)?',['טלפונים בעלי תכונות מוגבלות מספקים תמיכה מוגבלת בהתקנת אפליקציות','טלפונים בעלי תכונות מוגבלות דומים לטלפונים חכמים (Smartphones) אך הם גדולים יותר','טלפונים בעלי תכונות מוגבלות הם הדור הבא של הטלפונים החכמים, בעלי פונקציונליות מורחבת','טלפונים בעלי תכונות מוגבלות כוללים מצלמה, GPS וחיישנים נוספים מובנים'],[0],'Feature Phone מאפשר שיחות, הודעות ואינטרנט בסיסי, עם תמיכה מוגבלת בלבד בהתקנת אפליקציות.')
q('1.4','סוג אפליקציה','הצוות שלך מפתח משחק Android העושה שימוש בתכונות מכשיר רבות, כגון מצלמה, GPS וכיוון המכשיר. אם שימוש מדויק בתכונות הספציפיות של המכשיר הוא חיוני, איזה מסוגי האפליקציות הבאים הוא המתאים ביותר?',['אפליקציה היברידית (Hybrid app)','אפליקציית ווב לנייד (Mobile web app)','אפליקציית נייטיב (Native app)','אפליקציית שולחן עבודה (Desktop app)'],[2],'אפליקציית Native ניגשת ישירות ובאופן המלא ביותר לחומרת המכשיר.')
q('1.5','החלטות ארכיטקטורה','הצוות שלך מפתח אפליקציית iOS המשמשת לרישום משתמשים, כתובות הדוא"ל וכתובות המגורים שלהם. הנתונים מועברים לשרת ומשמשים למשלוח דוגמיות של מוצרים פיזיים בדואר רגיל למשתמשים הרשומים. אילו מההחלטות הארכיטקטוניות הבאות הן המתאימות ביותר לשקול עבור אפליקציה זו?',['מחובר תמיד (Always Connected)','אפליקציית נייטיב (Native app)','אחסון והעברה (Store and forward)','נתונים סלולריים (Cellular data)','אפליקציית ווב (Web app)'],[1,2],'אפליקציית iOS נבנית כ-Native; אין צורך בחיבור רציף — הנתונים נשמרים ונשלחים כשיש חיבור (Store and Forward).')
q('1.6','גישת כיסוי','נתוני האנליטיקה שלך מראים שכל המשתמשים שלך משתמשים ב-iPhone. איזו מההחלטות הבאות היא המתאימה ביותר לאסטרטגיית הבדיקות שלך, אם מדובר באפליקציה בסיכון נמוך?',['שימוש בשירות גישה מרחוק למכשירים (Remote device access service)','שימוש באסטרטגיית פלטפורמה יחידה (Single platform strategy)','שימוש באסטרטגיית כיסוי מרבי (Maximum coverage strategy)','שימוש בסימולטורים של iOS בלבד'],[1],'כל המשתמשים על פלטפורמה אחת והסיכון נמוך — גישת Single Platform היא הזולה והמתאימה.')
q('1.7','אתגרי בדיקות','איזה מהבאים אינו מהווה אתגר בעת בדיקת אפליקציות למכשירים ניידים?',['פרמטרי פקודה לא ידועים להפעלת האפליקציה, המשנים את התנהגותה','גיוון של משתמשים וקבוצות משתמשים','סוגי רשתות וספקי תקשורת מרובים','חוסר זמינות של מכשירים חדשים שהושקו, המחייב שימוש באמולטורים/סימולטורים'],[0],'גיוון משתמשים, ריבוי רשתות ומכשירים חדשים הם אתגרים מוכרים במובייל. פרמטרי פקודה אינם אחד מהם.')
q('1.8','Crowd Testing','חברה החליטה להשתמש בבדיקות המונים (Crowd testing). איזה מהסיכונים הבאים מופחת בעקבות החלטה זו?',['חוסר זמינות של בעלי עניין חשובים במהלך הפיתוח','העלות של תמיכה בפלטפורמות מרובות','חוסר זמינות של מכשירים חשובים במהלך הבדיקות','ביקורות טובות בחנות האפליקציות של ספק הפלטפורמה'],[2],'בודקי ההמונים משתמשים במכשירים שלהם — וכך מצמצמים את סיכון זמינות המכשירים.')
q('2.1.1','מאפייני מכשיר','בעת בדיקת אפליקציית נייטיב (Native app) העושה שימוש בתכונות מכשיר שונות, באיזה מרכיבי החומרה הבאים הכי פחות נדרש להתמקד בעת ביצוע הבדיקות?',['רכיב WLAN','רמקולים מובנים','מצלמה מובנית','חיבור אוזניות'],[0],'רמקולים, מצלמה ואוזניות הם מאפייני מכשיר שהאפליקציה משתמשת בהם. WLAN הוא רכיב קישוריות כללי ופחות במוקד.')
q('2.1.3','התחממות יתר','איזו מהאפשרויות הבאות אינה תוצאה אפשרית של התחממות יתר של מכשיר נייד בעת בדיקתו?',['האפליקציה הופכת לאיטית','תכונות של האפליקציה מפסיקות לעבוד','הסרת ההתקנה של האפליקציה','פונקציונליות לא תקינה של אפליקציות'],[2],'התחממות גורמת להאטה ולתקלות תפקוד — אך לא מסירה את התקנת האפליקציה.')
q('2.1.4','חיישני קלט','איזו מהטענות הבאות אינה מהווה תרחיש תקף לבדיקת מכשיר נייד בנוגע לחיישני קלט?',['אימות איכות אות ה-GPS שהתקבל','בדיקת פונקציונליות תקינה של הג׳ירוסקופ (Gyroscope)','תיקוף הנתונים המסופקים על ידי חיישן התנועה','גודל מסך תקין במצב אופקי ובמצב אנכי'],[3],'גודל מסך וכיוון קשורים לבדיקות תצוגה וכיוון מסך — לא לחיישני קלט.')
q('2.1.5','שיטות קלט','איזו מהאפשרויות הבאות מכילה בדיקות המתייחסות אך ורק לשיטות קלט (Input methods) שונות?',['החלקה למסך הבא, הקשה כפולה על לחצן, סריקת קוד QR, הקלטת שמע','צילום תמונה באמצעות המצלמה, שימוש במקלדת תוכנה (Soft keyboard), הדפסת תוכן המסך, שימוש בקואורדינטות GPS','גרירת אובייקט על המסך, פתיחת אפליקציה אחרת, לכידת תמונות, שליחת מסרון (SMS) לחבר','הצגת נתוני מיקום גיאוגרפי, ביצוע מדידות מרחק, שימוש באפליקציית שלט לטלוויזיה, לכידת סרטונים מהאינטרנט'],[0],'החלקה, הקשה כפולה, סריקת QR והקלטת שמע — כולן שיטות קלט. בשאר האפשרויות יש פעולות שאינן קלט (הדפסה, SMS, הצגת נתונים).')
q('2.1.6','שינוי כיוון מסך','אתה עובד כבודק מכשירים ניידים בחברה המפתחת אפליקציית ניווט. אחת הדרישות היא שהאפליקציה תפעל הן במצב אנכי והן במצב אופקי, תוך אספקת אותן תכונות למשתמש בצורה מדויקת. איזו מהאפשרויות הבאות מפרטת את ההיבטים הטובים ביותר שיש לקחת בחשבון לצורך אימות פונקציונליות תקינה בעת החלפת כיוון המסך?',['חיישן תנועה, סוגיות אבטחה, תקינות נתוני הפלט','סוגיות שימושיות (Usability), שימור נתוני הקלט, שמירה על המצב הנוכחי','מעברים שונים בכיוון המסך, בעיות ביצועים, תכונות ממשק משתמש','הפרעות WLAN, סוגיות רינדור (Rendering) בממשק המשתמש הגרפי, אובדן נתונים שהוזנו'],[1],'בשינוי כיוון בודקים שהממשק שמיש, שהנתונים שהוזנו נשמרים ושהאפליקציה שומרת על מצבה הנוכחי.')
q('2.1.7','הפרעות ביוזמת המשתמש','אתה עובד כמנהל בדיקות עבור בנק המפתח גרסה חדשה של תוכנת הבנקאות המקוונת שלו, המיושמת כאפליקציית ווב (Web application). אתה מתמקד בסובלנות האפליקציה לתקלות בעקבות הפרעות ביוזמת המשתמש. איזו מהאפשרויות הבאות תבחר כטובה ביותר למטרה זו?',['1 – 2 – 3','1 – 2 – 4','2 – 3 – 4','2 – 3 – 5'],[3],'העברה להמתנה, מענה לשיחה והפעלת "נא לא להפריע" הן פעולות של המשתמש. אזהרות סוללה והתראות זיכרון נמוך הן הפרעות שמקורן במערכת.',stem=['הצגת אזהרות על סוללה חלשה', 'העברת מכשירים ניידים למצב המתנה', 'מענה לשיחות נכנסות', 'התראת זיכרון נמוך', 'העברת המכשיר למצב "נא לא להפריע" (Do-not-disturb mode)'])
q('2.1.8','הרשאות גישה','חברת ביטוח בריאות שחררה גרסה מעודכנת של אפליקציית הלקוחות שלה, הכוללת תכונה הסורקת חשבונית מבית המרקחת ושולחת אותה לחברת הביטוח לצורך תשלום. לאחר העדכון, הלקוחות גילו שלא ניתן להפעיל את המצלמה כדי לסרוק את החשבוניות. התקלה תוקנה. איזו מהבדיקות הבאות תבצע בתור החשובה ביותר בתרחיש הנתון?',['בדיקת ביצועים','בדיקת נגישות','בדיקת הרשאות גישה','בדיקת התקנה'],[2],'המצלמה לא נפתחת לאחר עדכון — חשד מרכזי הוא הרשאת המצלמה, ולכן יש לבדוק הרשאות גישה.')
q('2.2.1','בדיקות התראות','החברה שלך מספקת אפליקציית עדכוני חדשות הכוללת התראות להצגת מבזקים עם קישור עמוק (Deep linking) לדפי החדשות הרלוונטיים. משתמשים התלוננו על עיכובים בהצגת ההתראות, ולעיתים ההתראות לא הוצגו כלל. גורם השורש זוהה ותוקן. אילו בדיקות פונקציונליות תבצע כדי לאמת שהגרסה המתוקנת פועלת כראוי?',['1 – 4 – 5','1 – 2 – 4','1 – 2 – 5','2 – 3 – 4'],[2],'הצגת התראה כשהאפליקציה ברקע, התנהגות במצב סוללה חלשה והקישור העמוק הן בדיקות פונקציונליות של ההתראות. ביצועים ושימושיות אינם בדיקות פונקציונליות.',stem=['הצגה תקינה של ההתראה כאשר האפליקציה פועלת ברקע', 'הרצת האפליקציה בתנאי סוללה חלשה', 'בדיקת ביצועי האפליקציה בזמן הצגת ההתראה', 'ביצוע בדיקות שימושיות הקשורות לגרסה המתוקנת', 'בדיקת הקישור העמוק לדף החדשות הנכון'])
q('2.2.2','קישורי גישה מהירה','החברה שלך מפתחת גרסה חדשה של אפליקציה היברידית להשוואת מחירים, הכוללת פונקציונליות הנגישה באמצעות קישורי גישה מהירה. משימתך היא לאמת שקישורי הגישה המהירה פועלים ללא תקלות. איזו מהאפשרויות הבאות היא הגישה הטובה ביותר?',['אימות ההתנהגות התקינה של תכונת ה-Force Touch באפליקציית iOS','וידוא קיומן של סימניות מועדפות בדפדפן Chrome לנייד במערכת Android','אימות שכל מקשי החומרה במכשיר הנייד פועלים כצפוי','שימוש בכלי מתאים לזיהוי קישורים שבורים באפליקציית הווב לנייד'],[0],'קישורי גישה מהירה ב-iOS מופעלים באמצעות Force Touch / Quick Actions על אייקון האפליקציה.')
q('2.2.4','סוג בדיקה לא רלוונטי','אתה בודק אפליקציית iOS נייטיב (Native) המשתמשת בחיישנים שונים. איזה מסוגי הבדיקות הבאים אינו רלוונטי?',['בדיקות ביצועים','בדיקות של ניצול תכונות המכשיר','בדיקות בין-דפדפנים (Cross-browser)','בדיקות תאימות מכשיר'],[2],'אפליקציית Native אינה רצה בדפדפן — בדיקות Cross-browser אינן רלוונטיות.')
q('2.2.6','Interoperability','איזו מהאפשרויות הבאות היא סוג בדיקה אופייני לבדיקת יכולת פעולה הדדית (Interoperability) עם גרסאות של מערכת ההפעלה?',['בדיקות לזיהוי בעיות אבטחה','בדיקות לזיהוי בעיות ביצועים','בדיקות תקני נגישות','בדיקות תאימות לאחור'],[3],'פעולה הדדית עם גרסאות מערכת הפעלה נבדקת באמצעות בדיקות תאימות לאחור (Backward Compatibility).')
q('2.2.6','Co-existence','איזו מהאפשרויות הבאות היא מטרת בדיקה עיקרית בעת ביצוע בדיקות דו-קיום (Coexistence) של מערכת תחת בדיקה (SUT) עם אפליקציות אחרות במכשיר?',['אימות שהמערכת תחת בדיקה (SUT) אינה פוגעת בנתוני משתמש כלשהם','זיהוי בעיות אבטחה קיימות במכשיר','הערכת בעיות שימושיות במערכת תחת בדיקה (SUT)','בדיקה האם המערכת תחת בדיקה (SUT) עומדת בתקני נגישות'],[0],'בדיקות דו-קיום מוודאות שהאפליקציה פועלת לצד אפליקציות אחרות בלי לפגוע בהן או בנתוני המשתמש.')
q('2.1.1','בדיקות קישוריות','אתה מפתח גישת בדיקות לביצוע בדיקות קישוריות (Connectivity) בסוגים שונים של מכשירים ניידים. איזו מהאפשרויות הבאות אינה אמורה להיות בהיקף (Scope) של גישה זו?',['מעבר מ-GSM למצב טיסה ובחזרה ל-GSM','ביצוע עסקת תשלום באמצעות NFC','שימוש ב-Bluetooth לצורך צימוד (Pairing) למכשיר לביש (Wearable)','חיבור כבל USB לספק כוח'],[3],'חיבור לספק כוח הוא טעינה — אין בו העברת נתונים, ולכן אינו חלק מבדיקות קישוריות.')
q('3.1.1','בדיקות התקנה','הוטלה עליך המשימה לבצע בדיקות התקנה עבור אפליקציית Android. באיזו מבדיקות ההתקנה הבאות אין להשתמש?',['הרצת App-Installer.exe','התקנה באמצעות חיבור המכשיר למחשב והרצת פקודות התקנה','התקנה מתוך תוכנית הבטא של Google Play','התקנה עוקפת (Side-loading) על ידי אספקת חבילת ההתקנה בכרטיס זיכרון (SD-Card) והרצתה מתוך מערכת הקבצים של המכשיר'],[0],'קובץ ‎.exe הוא מתקין של Windows — אינו שיטת התקנה לאפליקציית Android.')
q('3.1.3','בעיות אבטחה','אילו מהאפשרויות הבאות הן בעיות אבטחה פוטנציאליות באפליקציות לנייד?',['הזרקת קוד (Code injection) דרך שדות קלט','העברת נתונים ללא הצפנה','האפליקציה אינה מגיבה לאחר הפרעה','בעיות רינדור לאחר שינוי כיוון המכשיר (Orientation)','חפיפה של אלמנטים על המסך במסכים קטנים'],[0,1],'הזרקת קוד ותעבורה לא מוצפנת הן חולשות אבטחה. שאר האפשרויות הן בעיות תפקוד ותצוגה.')
q('3.1.4','Time Behavior','באיזו מהאפשרויות הבאות סביר שתשתמש כדי לבצע בדיקת ביצועים של התנהגות בזמן (Time behavior) של אפליקציה?',['גרסת בנייה (Build) המכילה קוד ניטור (Instrumented build) לקבלת נתוני זמן מדויקים','מחולל עומסים לבחינת התנהגות השרת תחת עומס כבד','הרצת האפליקציה על אמולטור/סימולטור','מכשיר וסטופר לבדיקת ביצועי המכשיר'],[3],'מדידת זמנים (Chronometry) מבוצעת על מכשיר אמיתי עם סטופר — כך נמדדת חוויית הזמן של המשתמש.')
q('3.1.5','בדיקות שימושיות','הוטלה עליך המשימה לבצע בדיקות שימושיות לאפליקציה לנייד (Mobile app). איזה מהצעדים הבאים לא תבצע?',['לבקש מהמנהל להזמין מפגש במעבדת שימושיות (Usability lab)','לבדוק את תאימות האפליקציה להנחיות ממשק המשתמש של הפלטפורמה','להפעיל את תכונת קורא המסך (Voice-Over) של המכשיר','ללמוד על ציפיות המראה והתחושה (Look and feel) של הפלטפורמה'],[2],'קורא מסך שייך לבדיקות נגישות — לא לבדיקות שימושיות.')
q('3.1.6','CRUD','למה מתייחסים ראשי התיבות "CRUD" בהקשר של בדיקות תיקוף נתונים (Data validation testing)?',['Copy, Rename, Update, Delete','Create, Read, Undo, Delete','Create, Read, Update, Delete','Create, Read, Undo, Deploy'],[2],'CRUD = Create, Read, Update, Delete — ארבע הפעולות הבסיסיות על נתונים.')
q('3.1.7','בינאום','אתה מבצע בדיקות בינאום (Internationalization testing). במהלך הרצת הבדיקות, אתה רואה חלק מהמחרוזות כפסאודו-מחרוזות (Pseudo-strings) וחלק כמחרוזות באנגלית. מהי הסיבה הסבירה ביותר לכך?',['תרגומים חסרים','מחרוזות באנגלית המוטמעות בקוד קשיח (Hard-coded)','הגדרות שפה שגויות במכשיר','תקלה שאירעה במהלך הבנייה (Build)'],[1],'מחרוזות שהופרדו מהקוד מוצגות כפסאודו-מחרוזות; מחרוזת שנשארה באנגלית הוטמעה בקוד ולא עברה לקובץ המשאבים.')
q('3.1.8','בדיקות נגישות','מדוע יש לבצע בדיקות נגישות?',['כדי לקבוע אם האפליקציה שמישה עבור משתמשים בעלי צרכים שונים','מכיוון שזו דרישה של ה-W3C ושל ספקי הפלטפורמה','כדי לבדוק את האפליקציה באופן מלא','מכיוון שקיימים מקרי בדיקה גנריים שחובה להריץ עבור כל אפליקציה'],[0],'מטרת בדיקות הנגישות היא לוודא שהאפליקציה שמישה גם עבור אנשים עם מוגבלויות וצרכים שונים.')
q('3.2.3','לאחר השחרור','אתה בודק בצוות המפתח אפליקציה לנייד. הצוות סיים את הגרסה הנוכחית של האפליקציה ושחרר אותה לחנות האפליקציות. איזה מהצעדים הבאים הוא הפעילות הבאה שלך?',['ארכוב תוצרי הבדיקה (Testware)','בדיקות לאחר שחרור (Post-release testing)','בדיקות לקבלת אישור מחנות האפליקציות','סגירת בדיקות (Test closure)'],[1],'לאחר הפרסום בחנות מתבצעות בדיקות Post-release — ניטור, משוב משתמשים ותקלות ייצור.')
q('3.3','Session-Based','אתה חבר צוות חדש בצוות הבודק אפליקציות לנייד. ראש הצוות מבקש ממך לבדוק את הקלטים של האפליקציה במשך שעה אחת, את הפונקציות במשך שעה אחת, ואת ההפרעות במשך שעה אחת, וכן הלאה. באיזו שיטה משתמש ראש הצוות?',['ניהול בדיקות מבוסס סיכונים (Risk-Based Test Management)','האצלת אחריות תפקידו אליך','ניהול בדיקות ביצועים','ניהול בדיקות מבוסס מפגשים (Session-Based Test Management)'],[3],'מפגשים עם נושא מוגדר (Charter) ופרק זמן קבוע (Time Box) — זהו Session-Based Test Management.')
q('3.2.1','Field Testing','איזו מהאפשרויות הבאות מהווה שיטה אפקטיבית לבדיקות שטח (Field testing)?',['שימוש בסיורים (Tours) כסוג של טכניקת בדיקות חוקרות','שימוש במעבדת מכשירים פנימית לביצוע בדיקות בטלפונים חכמים (Smartphones) שונים','שימוש בגישה מבוססת ענן','שימוש בכלי בדיקה לביצוע בדיקות אוטומטיות בדפדפנים לנייד'],[0],'בדיקות שטח מתבצעות בתנאים אמיתיים מחוץ למעבדה — סיורים (Tours) של בדיקות חקר מתאימים לכך במיוחד.')
q('3.4','פירמידת הבדיקות','מדוע נפוץ בפרויקטים של אפליקציות לנייד להפוך את פירמידת הבדיקות (Test Pyramid)?',['בדיקות יחידה מסובכות הרבה יותר באפליקציות לנייד. כתוצאה מכך, נוח לבצע רק מעט בדיקות יחידה','חוסר בתמיכת כלים לבדיקות יחידה ואינטגרציה עבור אפליקציות לנייד','אפליקציות לנייד הן תמיד מונוליתיות. כתוצאה מכך, ניתן לבדוק הכול ברמת המערכת ואין צורך לבדוק ברמות נמוכות יותר','אפליקציות לנייד דורשות הרבה בדיקות ידניות, כמו בדיקות שימושיות או בדיקות שטח'],[1],'חוסר בכלים לבדיקות יחידה ואינטגרציה במובייל מוביל לריבוי בדיקות ברמות הגבוהות — פירמידה הפוכה.')
q('4.1','סביבות פיתוח','איזו מהטענות הבאות נכונה לגבי סביבות הפיתוח המשמשות לפיתוח אפליקציות לנייד?',['מפתחי iOS משתמשים ב-Visual Studio IDE כסביבת הפיתוח שלהם','מפתחי Android משתמשים ב-Universal Studio IDE, בעוד שמפתחי iOS משתמשים ב-Xcode כסביבת הפיתוח שלהם','מפתחי Android משתמשים ב-Xcode IDE כסביבת הפיתוח שלהם','מפתחי iOS משתמשים ב-Xcode IDE כסביבת הפיתוח שלהם'],[3],'Xcode היא סביבת הפיתוח הרשמית של Apple ל-iOS. מפתחי Android משתמשים ב-Android Studio.')
q('4.2','יכולות SDK','איזו מהאפשרויות הבאות אינה משימה שניתן לבצע בדרך כלל באמצעות ערכת פיתוח תוכנה (SDK) לאפליקציות לנייד?',['לכידת צילומי מסך','תכנון מקרי בדיקה','שליחת אירועים אקראיים לאפליקציה','יצירת מכשירים וירטואליים'],[1],'ה-SDK מספק כלים לצילומי מסך, אירועים אקראיים (Monkey) ומכשירים וירטואליים (AVD). תכנון מקרי בדיקה הוא פעילות של הבודק.')
q('4.3','אמולטורים וסימולטורים','אתה משמש כבודק של אפליקציה לנייד בעלת ארכיטקטורת לקוח-שרת. כדי לנצל טוב יותר את הציוד הזמין, החברה החליטה להשתמש במחשב האישי של המפתח, ללא חיבור האפליקציה לשרת אמיתי, כדי לבדוק את התכונות הבסיסיות בשלבים המוקדמים. איזו מהארכיטקטורות הבאות תמליץ למפתח של אפליקציית ה-Android ליישם כדי לאמת את ההתאמה התפקודית (Functional suitability) של התכונות הבסיסיות?',['התקנת אמולטור של השרת במחשב המפתח, והתקנת סימולטור של האפליקציה במכשיר נייד אמיתי','התקנת סימולטור של האפליקציה באחד מאמולטורי המכשירים הווירטואליים של Android (AVD), והתקנת אמולטור של השרת במחשב המפתח','התקנת סימולטור של השרת במחשב המפתח, והתקנת האפליקציה באחד מאמולטורי המכשירים הווירטואליים של Android (AVD)','התקנת סימולטור של השרת והתקנת האפליקציה באמולציה, ישירות במחשב המפתח'],[2],'השרת מוחלף בסימולטור (מדמה את התשובות שלו), והאפליקציה עצמה רצה על אמולטור AVD — הכל על מחשב המפתח.')
q('4.4','מעבדת בדיקות','אתה מנהל הבדיקות בחטיבת בנקאות דיגיטלית בחברת פינטק, המשדרגת אפליקציית בנקאות לנייד המבוססת על Android. השדרוג כולל מנגנון אבטחה חדשני המשתמש בזיהוי טביעת אצבע ופנים. איזו מהגישות הבאות מייצגת את הגישה הטובה ביותר להקמת מעבדת הבדיקות עבור שדרוג זה?',['הקמת מעבדת בדיקות מרוחקת כדי לבדוק את אפליקציית הבנקאות החדשנית על כמה שיותר סוגי מכשירים ניידים','הקמת מעבדת בדיקות פנים-ארגונית (On-premise) כדי לבדוק ביעילות את התכונות החדשות והייחודיות של האפליקציה, הקשורות ליכולות המכשיר הנייד','הקמת מעבדת בדיקות מרוחקת לסוגים רבים של מכשירים, ומעבדת בדיקות פנים-ארגונית כדי להשיג כיסוי מרבי של מכשירים אפשריים','הקמת מעבדת בדיקות מרוחקת כדי לבדוק את האפליקציה על סוגים רבים של מכשירי Android מיצרנים שונים ולחסוך כסף לחברה'],[1],'טביעת אצבע וזיהוי פנים דורשים אינטראקציה פיזית עם החיישנים — מעבדה מקומית מתאימה לכך ושומרת על אבטחת המידע.')
q('5.1','גישות לאוטומציה','איזו מהטענות הבאות אינה מבחינה בצורה נכונה בין הגישות הנפוצות לאוטומציה של בדיקות במכשירים ניידים?',['גישת בדיקות מבוססת-סוכן (Agent-based) מתאימה בעיקר להרצת אפליקציות ווב לנייד, בעוד שגישת בדיקות מבוססת-מכשיר (Device-based) מתאימה לכל סוגי האפליקציות לנייד','גישת בדיקות מבוססת-סוכן משתמשת במחרוזות הנשלחות על ידי הדפדפן כדי לזייף דפדפן מסוים, בעוד שגישת בדיקות מבוססת-מכשיר חייבת להתבצע על גבי מכשיר ספציפי','אפליקציות נייטיב (Native apps) נבדקות בצורה הטובה ביותר באמצעות כלי אוטומציה כלליים לאפליקציות ווב, בעוד שאפליקציות לנייד דורשות כלים ייעודיים','אופן הפעולה של הגישה מבוססת-הסוכן הוא חיקוי מאפייני הדפדפן, בעוד שאופן הפעולה של הגישה מבוססת-המכשיר הוא הרצה על גבי הדפדפן הממשי'],[2],'אפליקציות Native אינן רצות בדפדפן — אי אפשר לבדוק אותן בכלי אוטומציה לאפליקציות ווב.')
q('5.2','שיטות תסריט','איזו מהטענות הבאות נכונה לגבי שיטות כתיבת התסריטים (Scripting) המשמשות באוטומציה של בדיקות מכשירים ניידים?',['תסריט המבוסס על זיהוי אובייקטים מהיר יותר מתסריט המבוסס על זיהוי ויזואלי (OCR/זיהוי טקסט), ולכן מקצר את הזמן הכולל הנדרש להרצת הבדיקות','תסריט מבוסס-אובייקטים הוא השיטה האמינה יותר לפיתוח קוד אוטומציה, כיוון שהוא מאפשר לתשתית הבדיקה להתאים את האובייקט הנכון באפליקציה באופן שאינו תלוי במכשיר הנבדק','שיטת תסריט המשתמשת בזיהוי אובייקטים מגבירה את מאמצי התחזוקה השוטפים כאשר ישנם שינויי קוד תכופים באפליקציה המשפיעים על תמונות הייחוס (Baseline images)','הסתמכות על OCR/זיהוי טקסט ועל למידת אובייקטים אינה מהווה סיכון לאמינות או ליציבות של אוטומציית הבדיקות'],[1],'זיהוי לפי אובייקט אינו תלוי ברזולוציה או במראה המסך — לכן הוא אמין יותר. תמונות ייחוס שייכות לשיטת ה-Image/OCR.')
q('5.3','הערכת כלים','איזו מהאפשרויות הבאות אינה שיקול מרכזי בעת הערכת כלי אוטומציה לבדיקות במכשירים ניידים?',['סט כישורי אוטומציית הבדיקות של הבודקים שישתמשו בכלי','דרישות ומורכבות אוטומציית הבדיקות, כגון שימוש של האפליקציה בתכונות חדשות כמו FaceID, זיהוי טביעת אצבע או צ׳טבוטים','חשוב לקחת בחשבון את דרישות ומורכבויות האוטומציה','יכולתה של תשתית הבדיקות לפעול באופן עצמאי, ללא תלות בכלים קיימים אחרים שבשימוש הארגון'],[3],'כלי טוב צריך דווקא להשתלב עם הכלים הקיימים בארגון (Integrations) — עצמאות מהם אינה שיקול מרכזי.')
q('5.4','מעבדה מרוחקת','איזו מהטענות הבאות תומכת במידה הפחותה ביותר בשימוש במעבדת בדיקות מרוחקת?',['בדיקות בשלבים מאוחרים יותר של פיתוח האפליקציה, הדורשות הרצה על מעבדת מכשירים מלאה, מבוצעות בצורה הטובה ביותר במעבדת מכשירים מרוחקת','מעבדת מכשירים מרוחקת תכסה ככל הנראה קבוצה קטנה של תצורות מכשיר/מערכת הפעלה עדכניות, כדי לאפשר למפתחים ולבודקים לאמת במהירות שלבי עיצוב מוקדמים של האפליקציה','מעבדות מכשירים מרוחקות יבטיחו מגוון מספיק של מכשירים ומערכות הפעלה, כדי לאפשר לצוותים להשיג מגוון רחב יותר של מכשירים עבור הבדיקות שלהם','מעבדות מרוחקות עדיפות בעת הרצה בהיקף נרחב, מכיוון שהן מתוכננות בדרך כלל כך שברוב המקרים חששות מבעיות יציבות מוסרים מהתהליך הכולל'],[1],'היתרון של מעבדה מרוחקת הוא מגוון רחב והיקף הרצה גדול. קבוצה קטנה של תצורות עדכניות לשלבים מוקדמים אינה מצדיקה אותה.')
